usage:
const fullPad = require('@yash580o/full-pad');
// Example 1: Pad with '*', 3 times
console.log(fullPad("hello world", "*", 3));
// Output: ***hello***world***

// Example 2: Pad with '-', 2 times
console.log(fullPad("foo bar", "-", 2));
// Output: --foo--bar--

// Example 3: No padding
console.log(fullPad("test", "", 0));
// Output: test
